Here is a small self-contained version:

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Click Counter</title>
  <style>
    body { font-family: system-ui, sans-serif; display: grid; place-items: center; min-height: 100vh; }
    button { font-size: 1rem; padding: 0.7rem 1rem; }
  </style>
</head>
<body>
  <button id="counter">Clicked 0 times</button>
  <script>
    let count = 0;
    const button = document.querySelector('#counter');
    button.addEventListener('click', () => {
      count += 1;
      button.textContent = `Clicked ${count} ${count === 1 ? 'time' : 'times'}`;
    });
  </script>
</body>
</html>
```

Save it as `index.html` and open it in a browser.

The usual fix is to let the grid columns shrink safely.

Use:

```css
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1rem;
}

.card {
  min-width: 0;
}
```

`minmax(min(100%, 18rem), 1fr)` prevents a card from demanding more than the viewport width. `min-width: 0` helps text and child elements shrink instead of forcing overflow.

```js
import { readFile } from 'node:fs/promises';

const path = process.argv[2];

if (!path) {
  console.error('Usage: node count-records.js <file.json>');
  process.exit(1);
}

const raw = await readFile(path, 'utf8');
const data = JSON.parse(raw);

if (!Array.isArray(data)) {
  console.error('Expected the JSON file to contain an array.');
  process.exit(1);
}

console.log(`Records: ${data.length}`);
```

Run it with:

```powershell
node count-records.js .\data.json
```

```ts
type ApiError = {
  code: string;
  message: string;
  retryable?: boolean;
};

type ApiResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: ApiError };

async function loadUser(id: string): Promise<ApiResult<{ id: string; email: string }>> {
  const response = await fetch(`/api/users/${id}`);

  if (!response.ok) {
    return {
      ok: false,
      error: { code: String(response.status), message: 'Request failed', retryable: response.status >= 500 },
    };
  }

  return { ok: true, data: await response.json() };
}
```

The `ok` flag makes TypeScript narrow the shape cleanly.

```js
import express from 'express';
import { z } from 'zod';

const app = express();
app.use(express.json());

const CreateNote = z.object({
  title: z.string().min(1),
  body: z.string().min(1),
});

app.post('/notes', (req, res) => {
  const parsed = CreateNote.safeParse(req.body);

  if (!parsed.success) {
    return res.status(400).json({ error: 'Invalid request body', issues: parsed.error.issues });
  }

  const note = { id: crypto.randomUUID(), ...parsed.data };
  return res.status(201).json(note);
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

Validation at the route boundary keeps bad input from leaking into the rest of the app.
